function base62Encode(data, alphabet = REVERSED_B62) {
  if (typeof alphabet !== 'string' || alphabet.length !== 62) throw new Error('Invalid base62 alphabet');

  const buf = Buffer.isBuffer(data) ? data : Buffer.from(data);
  const zeros = leadingZeroBytes(buf);

  let num = 0n;
  for (const b of buf) num = (num << 8n) + BigInt(b);

  if (num === 0n) return alphabet[0].repeat(zeros);

  let encoded = '';
  const base = 62n;
  while (num > 0n) {
    const rem = num % base;
    encoded = alphabet[Number(rem)] + encoded;
    num /= base;
  }

  return alphabet[0].repeat(zeros) + encoded;
}

