function base64Encode(data, alphabet = REVERSED_B64, pad = '#') {
    const buf = Buffer.from(data);
    if (!buf.length) return '';
    const out = [];
    for (let i = 0; i < buf.length; i += 3) {
        const c = buf.slice(i, i + 3);
        let n = 0; for (const b of c) n = (n << 8) | b;
        n <<= 8 * (3 - c.length);
        for (let s = 0; s < c.length + 1; s++) out.push(alphabet[(n >> (18 - s * 6)) & 63]);
        for (let p = 0; p < 3 - c.length; p++) out.push(pad);
    }
    return out.join('');
}

