// Custom URL encoding scheme:
// - alphanumeric chars are safe (not encoded)
// - space becomes '+'
// - ALL other chars (including '.', '-', '~', '_') are percent-encoded
// - percent encoding uses LOWERCASE hex digits

function hexByte(byte) {
    return '%' + byte.toString(16).padStart(2, '0');
}

function isAlphanumeric(ch) {
    const c = ch.charCodeAt(0);
    return (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122);
}

