function retry(fn, options = {}) {
    const maxAttempts = options.maxAttempts ?? 3;
    const baseDelay = options.baseDelay ?? 0;

    if (typeof fn !== 'function') {
        return Promise.reject(new TypeError('retry requires a function'));
    }
    if (!Number.isInteger(maxAttempts) || maxAttempts < 1) {
        return Promise.reject(new TypeError('maxAttempts must be a positive integer'));
    }
    if (typeof baseDelay !== 'number' || baseDelay < 0) {
        return Promise.reject(new TypeError('baseDelay must be a non-negative number'));
    }

    return (async () => {
        let lastError;
        for (let attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return await fn(attempt);
            } catch (e) {
                lastError = e;
                if (attempt >= maxAttempts) {
                    throw new RetryError('Retry failed', attempt, lastError);
                }
                const waitMs = baseDelay * Math.pow(2, attempt - 1);
                if (waitMs > 0) await delay(waitMs);
            }
        }
        throw new RetryError('Retry failed', maxAttempts, lastError);
