// Custom template engine with specific syntax rules:
// - {{var}} for variable substitution
// - {{var|filter}} for filtered substitution
// - {{#if var}}...{{/if}} for conditionals
// Filters are: upper, lower, capitalize, reverse

function applyFilter(value, filter) {
    switch (filter) {
        case 'upper': return String(value).toUpperCase();
        case 'lower': return String(value).toLowerCase();
        case 'capitalize': return String(value).charAt(0).toUpperCase() + String(value).slice(1).toLowerCase();
        case 'reverse': return String(value).split('').reverse().join('');
        default: return String(value);
    }
}

function renderSimple(template, data) {
    return template.replace(/\{\{(\w+)(?:\|(\w+))?\}\}/g, (match, key, filter) => {
        const val = data[key] !== undefined ? data[key] : '';
        return filter ? applyFilter(val, filter) : String(val);
    });
}

assert.strictEqual(renderSimple('Hello {{name}}!', { name: 'world' }), 'Hello world!');
assert.strictEqual(renderSimple('{{msg|upper}}', { msg: 'hi' }), 'HI');

