function render(template, data) {
    // Process innermost conditionals first, then work outward
    let result = template;
    let prev;
    do {
        prev = result;
        result = result.replace(/\{\{#if (\w+)\}\}((?:(?!\{\{#if )[\s\S])*?)\{\{\/if\}\}/g, (match, key, body) => {
            const val = data[key];
            if (val && val !== '' && val !== 0 && val !== false) {
                return body;
            }
            return '';
        });
    } while (result !== prev);
    // Then substitute variables
    return renderSimple(result, data);
}

