// Custom iterator factory library
// Each factory returns an object with next() that returns { value, done, index }
// Unlike standard iterators, 'done' is true ON the last valid item (not after it)

function rangeIter(start, end) {
    let i = start;
    return {
        next() {
            if (i >= end) return { value: undefined, done: true, index: -1 };
            const val = i++;
            return { value: val, done: i >= end, index: val - start };
