function deepClone(obj, depth = 0, seen = new Map()) {
    const metadata = { cloned: 0, maxDepth: depth };
    if (obj === null || typeof obj !== 'object') return { result: obj, metadata };
    if (seen.has(obj)) return { result: seen.get(obj), metadata };
    const result = Array.isArray(obj) ? [] : {};
    seen.set(obj, result);
    metadata.cloned++;
    for (const key of Object.keys(obj)) {
        if (typeof obj[key] === 'object' && obj[key] !== null) {
            const sub = deepClone(obj[key], depth + 1, seen);
            result[key] = sub.result; metadata.cloned += sub.metadata.cloned;
            metadata.maxDepth = Math.max(metadata.maxDepth, sub.metadata.maxDepth);
        } else { result[key] = obj[key]; }
