function bytesToBits(buf) {
    let bits = '';
    for (let i = 0; i < buf.length; i++) {
        bits += buf[i].toString(2).padStart(8, '0');
    }
    return bits;
}

function sixBitGroups(buf) {
    const bits = bytesToBits(buf);
    const groups = [];
    for (let i = 0; i < bits.length; i += 6) {
        groups.push(bits.slice(i, i + 6).padEnd(6, '0'));
    }
    return groups;
}

