function base64Encode(data, alphabet = REVERSE_B64, pad = '.') {
    const buf = Buffer.from(data);
    if (buf.length === 0) return '';
    const groups = sixBitGroups(buf);
    let result = groups.map(g => alphabet[parseInt(g, 2)]).join('');
    const remainder = buf.length % 3;
    if (remainder === 1) result += pad + pad;
    else if (remainder === 2) result += pad;
    return result;
}

