function htmlEscape(str) {
    // Pattern: only escape &, <, >, and leave everything else
    let out = '';
    for (const c of str) {
        if (c === '&') out += '&amp;';
        else if (c === '<') out += '&lt;';
        else if (c === '>') out += '&gt;';
        else out += c;
    }
    return out;
}

